import React from 'react';
import { Play, Calendar, Home, Globe, ChevronRight, AlertCircle, Clock } from 'lucide-react';

const ScheduleGenerator = ({ 
  examDays, examDates, setExamDates, handleExamDayChange,
  startTime, setStartTime, selectedYear, setSelectedYear,
  sectionCount, setSectionCount, proctorSource, setProctorSource,
  roomSource, setRoomSource, onGenerate, onClearSchedule,
  generationErrors, deptCode, globalSchedule 
}) => {

  // FEATURE 1: Heatmap logic to check resource usage
  const getHeatColor = (type, name) => {
    const usage = globalSchedule.filter(s => s[type] === name).length;
    if (usage > 5) return 'border-rose-500 text-rose-500 bg-rose-50'; 
    if (usage > 2) return 'border-amber-500 text-amber-500 bg-amber-50';
    return 'border-emerald-500 text-emerald-500 bg-emerald-50';
  };

  return (
    <div className="space-y-8 animate-in zoom-in-95 duration-300">
      {generationErrors.length > 0 && (
        <div className="bg-rose-50 border-2 border-rose-200 rounded-[2.5rem] p-8">
          <div className="flex items-center gap-4 mb-6 text-rose-600">
            <AlertCircle size={32} />
            <h5 className="font-black uppercase tracking-tighter text-xl">Schedule Halted</h5>
          </div>
          <div className="space-y-3">
            {generationErrors.map((err, i) => (
              <div key={i} className="bg-white/60 p-4 rounded-2xl flex justify-between items-center border border-rose-100">
                <span className="text-xs font-black text-slate-800">{err.issue}</span>
                <p className="text-[10px] font-bold text-slate-600 uppercase">{err.resolution}</p>
              </div>
            ))}
          </div>
        </div>
      )}

      <div className="bg-slate-900 rounded-[3.5rem] p-12 text-white shadow-2xl relative overflow-hidden">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-16 relative z-10">
          <div className="space-y-10">
            <h4 className="flex items-center gap-3 text-blue-400 font-black text-[10px] uppercase tracking-[0.4em]">
                <div className="w-10 h-1 bg-blue-400 rounded-full"/> Timeline Config
            </h4>
            <div className="space-y-6">
                <input type="number" value={examDays || ''} onChange={e => handleExamDayChange(e.target.value)} placeholder="Exam Days" className="w-full bg-slate-800/50 p-6 rounded-[2rem] text-3xl font-black text-blue-400 border-2 border-slate-700 outline-none focus:border-blue-500" />
                <div className="space-y-3 max-h-48 overflow-y-auto pr-4 custom-scrollbar">
                    {examDates.map((d, i) => (
                    <div key={i} className="flex items-center bg-slate-800 p-4 rounded-2xl border border-slate-700">
                        <span className="text-blue-500 font-black text-[10px] w-14">DAY {i+1}</span>
                        <input type="date" value={d} onChange={e => {
                            const updated = [...examDates];
                            updated[i] = e.target.value;
                            setExamDates(updated);
                        }} className="w-full bg-transparent text-xs font-black text-white outline-none" />
                    </div>
                    ))}
                </div>
                <input type="time" value={startTime} onChange={e => setStartTime(e.target.value)} className="w-full bg-slate-800/50 p-5 rounded-2xl font-black text-blue-400 border-2 border-slate-700" />
            </div>
          </div>

          <div className="space-y-10 flex flex-col">
            <h4 className="flex items-center gap-3 text-emerald-400 font-black text-[10px] uppercase tracking-[0.4em]">
                <div className="w-10 h-1 bg-emerald-400 rounded-full"/> Logic Parameters
            </h4>
            <div className="space-y-4 flex-1">
                <div className="grid grid-cols-2 gap-4">
                    <select value={selectedYear} onChange={e => setSelectedYear(e.target.value)} className="bg-slate-800/50 p-5 rounded-2xl font-black text-xs text-blue-400 border-2 border-slate-700 outline-none">
                        {[1, 2, 3, 4, 5].map(y => <option key={y} value={y}>Year {y}</option>)}
                    </select>
                    <input type="number" value={sectionCount || ''} onChange={e => setSectionCount(parseInt(e.target.value) || 0)} placeholder="Sections" className="bg-slate-800/50 p-5 rounded-2xl font-black text-emerald-400 border-2 border-slate-700 outline-none" />
                </div>

                {/* FEATURE 3: Load Balancing Visual Indicator */}
                <div className="bg-slate-800/30 p-4 rounded-2xl border border-slate-700 flex justify-between items-center">
                    <span className="text-[9px] font-black uppercase text-slate-500 tracking-widest">Load Balancing</span>
                    <div className="px-3 py-1 bg-emerald-500/20 text-emerald-500 rounded-lg text-[8px] font-black uppercase border border-emerald-500/30">Optimized</div>
                </div>

                <button onClick={() => setProctorSource(proctorSource === "Department" ? "Global" : "Department")} className="w-full bg-slate-800 p-5 rounded-2xl text-[10px] font-black uppercase flex justify-between items-center border border-slate-700">
                    <span className="flex items-center gap-3">{proctorSource === "Department" ? <Home size={14}/> : <Globe size={14}/>} Staff: {proctorSource}</span>
                    <ChevronRight size={14}/>
                </button>
            </div>
            <button onClick={onGenerate} className="w-full bg-blue-600 py-10 rounded-[3rem] font-black uppercase tracking-[0.4em] text-xl shadow-lg hover:bg-blue-500 transition-all flex items-center justify-center gap-4 group">
              <Play size={32} fill="currentColor" /> Start Calculation
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ScheduleGenerator;
